{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "An LEA would have to treat its school nurses as licensed personnel and pay them under the salary schedule the LEA adopts for licensed personnel for that school year.",
      "rationale": "Conveys the required classification and compensation under the LEA's licensed-personnel salary schedule for the respective school year."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill says it does not limit an LEA's ability to contract with the Tennessee public school nurse program, created by Section 68-1-1201, for school health services, or to set the terms of that contract, including a nurse's pay. It also does not apply to pay for the LEA's contractors.",
      "rationale": "Includes both the preservation of contracting authority and compensation terms and the exclusion of contractor compensation."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "A school nurse who is an LEA employee, holds a valid registered nurse license, is a Nationally Certified School Nurse through the National Board for Certification of School Nurses, and has zero years of experience must receive the same base salary as a licensed teacher with a bachelor's degree and zero years of experience.",
      "rationale": "States all eligibility conditions and the teacher base-salary benchmark; the surrounding salary-schedule discussion establishes the school-year context."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "A nurse employed by the LEA with more training and experience than that must receive more than the base salary.",
      "rationale": "Conveys mandatory above-base compensation for LEA-employed nurses exceeding the previously stated training and experience benchmark."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "A nurse with less training and experience must receive less than the base salary.",
      "rationale": "In context, conveys mandatory below-base compensation for LEA-employed nurses with less training and experience than the stated benchmark."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "A salary schedule adopted under subdivision (a)(1) could not reduce the salary of a school nurse already employed by the LEA when the schedule is adopted.",
      "rationale": "Includes the salary-reduction prohibition, applicable schedule, and employment-at-adoption condition."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The act would take effect July 1, 2026, and would apply to the 2026-2027 school year and each school year after that.",
      "rationale": "States the exact effective date and the initial and continuing school-year applicability."
    }
  ]
}
